-- Fictional, isolated. No external calls and no real notifications.
begin;
create function public.qa_assert(ok boolean,msg text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'ASSERTION: %',msg;end if;end$$;
create function public.qa_denied(q text) returns void language plpgsql as $$begin begin execute q;exception when others then return;end;raise exception 'Expected denial: %',q;end$$;
insert into auth.users(id,email) values
('00000000-0000-0000-0000-000000000001','owner@example.test'),('00000000-0000-0000-0000-000000000002','supervisor@example.test'),('00000000-0000-0000-0000-000000000003','worker@example.test'),('00000000-0000-0000-0000-000000000004','responder@example.test'),('00000000-0000-0000-0000-000000000005','outsider@example.test');
insert into public.admin_users values('00000000-0000-0000-0000-000000000002');
insert into public.support_requests(id,user_id,user_address,accused_name,accused_address,harassment_type,severity_level,description,allow_volunteer_support) values('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001','private','private','private','other','high','Fictional description',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
select set_config('request.jwt.claims','{"aal":"aal1"}',true);
select public.qa_denied($q$select public.vv_create_worker_invite('00000000-0000-0000-0000-000000000003','support_volunteer','bhopal')$q$);
select public.qa_assert(not exists(select 1 from public.support_requests),'Supervisor AAL1 cannot read raw contacts/cases');
select public.qa_denied($q$select public.vv_open_case('10000000-0000-0000-0000-000000000001')$q$);
select set_config('request.jwt.claims','{"aal":"aal2"}',true);
select public.vv_create_worker_invite('00000000-0000-0000-0000-000000000003','support_volunteer','bhopal') worker_token \gset
select public.vv_create_worker_invite('00000000-0000-0000-0000-000000000004','emergency_responder','bhopal') responder_token \gset
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000005',true);
select public.qa_denied(format('select public.vv_apply_worker(%L,%L,%L,%L,%L)',:'worker_token','Impostor','Test organisation','Hindi','Listening'));
select public.qa_denied($q$select * from public.vv_workforce_invites$q$);
select public.qa_denied($q$select public.vv_sos_apply('bhopal','Impostor')$q$);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
select public.vv_apply_worker(:'worker_token','Fictional worker','Test organisation','Hindi, English','Listening');
select public.qa_denied(format('select public.vv_apply_worker(%L,%L,%L,%L,%L)',:'worker_token','Reuse','Test organisation','Hindi','Listening'));
select public.qa_denied($q$select public.vv_review_worker('00000000-0000-0000-0000-000000000003','approved',true,'review-123')$q$);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',true);
select public.vv_apply_worker(:'responder_token','Fictional responder','Test organisation','Hindi','First aid');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
select public.qa_denied($q$select public.vv_review_worker('00000000-0000-0000-0000-000000000003','approved',false,'review-123')$q$);
select public.vv_review_worker('00000000-0000-0000-0000-000000000003','probation',true,'review-123');
select public.vv_review_worker('00000000-0000-0000-0000-000000000004','probation',true,'review-456');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
select public.vv_worker_availability(true);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
select public.vv_assign_case('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000003');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
select public.qa_assert(not public.vv_can_work_case('10000000-0000-0000-0000-000000000001'),'No conversation access before acknowledgment');
select public.qa_denied($q$select public.vv_accept_case('10000000-0000-0000-0000-000000000001',false)$q$);
select public.vv_accept_case('10000000-0000-0000-0000-000000000001',true);
select public.qa_assert(public.vv_can_work_case('10000000-0000-0000-0000-000000000001'),'Acknowledged worker can converse');
select public.qa_assert(not exists(select 1 from public.support_requests),'Assigned worker cannot read raw contact identities');
select set_config('request.jwt.claims','{"aal":"aal1","user_metadata":{"role":"admin"}}',true);
select public.qa_assert(not public.vv_can_work_case('10000000-0000-0000-0000-000000000001'),'AAL1 and editable metadata do not grant access');
select public.qa_denied($q$insert into public.comments(request_id,content) values('10000000-0000-0000-0000-000000000001','Forbidden')$q$);
select set_config('request.jwt.claims','{"aal":"aal2"}',true);
reset role;
insert into public.vv_case_evidence(id,request_id,uploader_id,kind,label,url,ready) values('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001','link','Private link','https://example.test/private',true);
set local role authenticated;
select public.qa_denied($q$select public.vv_open_evidence('20000000-0000-0000-0000-000000000001')$q$);
select public.qa_denied($q$select public.vv_set_evidence_grant('20000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000003',true)$q$);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select public.vv_set_evidence_grant('20000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000003',true);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
select public.qa_assert(public.vv_open_evidence('20000000-0000-0000-0000-000000000001')->>'url'='https://example.test/private','Explicit file grant releases destination');
-- Expiry and withdrawn grants are enforced independently of the UI.
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select public.vv_set_evidence_grant('20000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000003',false);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
select public.qa_assert(jsonb_array_length(public.vv_list_evidence('10000000-0000-0000-0000-000000000001'))=0,'Unshared evidence metadata is hidden');
select public.qa_denied($q$select public.vv_open_evidence('20000000-0000-0000-0000-000000000001')$q$);
reset role;
update public.vv_workforce set review_due=now()-interval '1 second' where user_id='00000000-0000-0000-0000-000000000003';
set local role authenticated;
select public.qa_assert(not public.vv_can_work_case('10000000-0000-0000-0000-000000000001'),'Expired review revokes access on current JWT');
reset role;
update public.vv_workforce set review_due=now()+interval '1 day' where user_id='00000000-0000-0000-0000-000000000003';
update public.vv_case_assignments set accepted_at=null,acknowledge_by=now()-interval '1 second' where user_id='00000000-0000-0000-0000-000000000003';
set local role authenticated;
select public.qa_denied($q$select public.vv_accept_case('10000000-0000-0000-0000-000000000001',true)$q$);
select public.qa_assert(jsonb_array_length(public.vv_my_assignments())=0,'Late assignment is hidden and inaccessible');
reset role;
update public.vv_case_assignments set accepted_at=now(),acknowledge_by=now()+interval '1 hour' where user_id='00000000-0000-0000-0000-000000000003';
set local role authenticated;
-- SOS: availability acceptance alone does not release location.
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
select public.vv_sos_set_area('bhopal','{"type":"Polygon","coordinates":[[[77,23],[78,23],[78,24],[77,24],[77,23]]]}','https://example.test/boundary',true);
select public.vv_sos_approve('00000000-0000-0000-0000-000000000004',true);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',true);
select public.vv_sos_duty(true,23.251,77.401);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select public.vv_sos_start('30000000-0000-0000-0000-000000000001','Fictional owner','[{"id":"40000000-0000-0000-0000-000000000001","name":"Fictional contact","phone":"+919999999991"}]','bhopal',false,true,false,jsonb_build_object('latitude',23.25,'longitude',77.4,'timestamp',extract(epoch from now())*1000,'accuracy',20));
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',true);
select public.vv_sos_accept('30000000-0000-0000-0000-000000000001');
select public.qa_assert(public.vv_sos_read('30000000-0000-0000-0000-000000000001')->>'latitude' is null,'Self-acceptance cannot disclose coordinates');
select public.qa_denied($q$select public.vv_dispatch_responder('30000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000004',true)$q$);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
select public.vv_dispatch_responder('30000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000004',true);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',true);
select public.qa_assert((public.vv_sos_read('30000000-0000-0000-0000-000000000001')->>'latitude')::numeric=23.25,'Explicit dispatched assignment releases location');
-- Survivor report revokes and hides report text from the accused.
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select public.vv_report_worker('00000000-0000-0000-0000-000000000004','Fictional report for local test',null,'30000000-0000-0000-0000-000000000001');
select public.vv_report_worker('00000000-0000-0000-0000-000000000003','Fictional report for local test','10000000-0000-0000-0000-000000000001');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',true);
select public.qa_denied($q$select public.vv_sos_read('30000000-0000-0000-0000-000000000001')$q$);
select public.qa_denied($q$select * from public.vv_safety_reports$q$);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
select public.qa_assert(not public.vv_can_work_case('10000000-0000-0000-0000-000000000001'),'Reporting removes worker conversation access');
select public.qa_denied($q$select public.vv_open_evidence('20000000-0000-0000-0000-000000000001')$q$);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
select public.qa_assert(jsonb_array_length(public.vv_worker_console()->'reports')=2,'Supervisor can investigate private reports');
select public.qa_denied($q$select public.vv_assign_case('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000003')$q$);
select public.vv_review_worker('00000000-0000-0000-0000-000000000003','suspended',false,'review-suspended');
select public.qa_assert(not public.vv_worker_eligible('00000000-0000-0000-0000-000000000003'),'Suspension revokes eligibility');
reset role;
select public.qa_assert(exists(select 1 from public.vv_case_events where action='evidence_opened'),'Sensitive evidence reads are audited');
select public.qa_assert(exists(select 1 from public.vv_sos_audit where action='precise_context_viewed'),'Precise emergency reads are audited');
rollback;
\echo 'Governance access checks passed: invite, MFA, review, assignment, evidence, dispatch, reporting, suspension.'
